-- Stable campaign snapshots and server-authoritative, authenticated rankings.
-- Client bestTimes/completed are convenience save data, never ranking evidence.
begin;
create schema if not exists svela_private;
revoke all on schema svela_private from public, anon, authenticated;
create table svela_private.puzzle_catalog (
  level_key text primary key check (length(level_key) between 1 and 64),
  catalog_version text not null,
  ranked boolean not null default true,
  pieces jsonb not null check (jsonb_typeof(pieces) = 'array' and jsonb_array_length(pieces) between 1 and 500)
);
create table svela_private.verified_discoveries (
  user_id uuid not null references auth.users(id) on delete cascade,
  level_key text not null references svela_private.puzzle_catalog(level_key),
  discovered_at timestamptz not null default clock_timestamp(),
  primary key (user_id, level_key)
);
create table svela_private.level_bests (
  user_id uuid not null references auth.users(id) on delete cascade,
  level_key text not null references svela_private.puzzle_catalog(level_key),
  best_ms integer not null check (best_ms between 1 and 86400000),
  primary key (user_id, level_key)
);
create index level_bests_ranking on svela_private.level_bests(level_key, best_ms, user_id);
create table svela_private.timed_runs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null unique references auth.users(id) on delete cascade,
  session_id text not null,
  level_key text not null references svela_private.puzzle_catalog(level_key),
  started_at timestamptz not null default clock_timestamp()
);
alter table svela_private.puzzle_catalog enable row level security;
alter table svela_private.verified_discoveries enable row level security;
alter table svela_private.level_bests enable row level security;
alter table svela_private.timed_runs enable row level security;
revoke all on all tables in schema svela_private from public, anon, authenticated;

