-- Each mutation takes the account deletion lock, then verifies the account still exists.
create function svela_private.require_account() returns uuid
language plpgsql security invoker set search_path = '' as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'Authentication required' using errcode = '28000'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_uid::text, 732641));
  if not exists (select 1 from auth.users where id = v_uid) then raise exception 'Account no longer exists' using errcode = '28000'; end if;
  return v_uid;
end;
$$;

-- Compare each removal with the still-occupied infinite exit ray, including core.
create function svela_private.verify_solution(p_key text, p_ids jsonb) returns boolean
language plpgsql stable security invoker set search_path = '' as $$
declare
  v_remaining jsonb;
  v_id jsonb;
  v_piece jsonb;
  v_other jsonb;
  v_axis integer;
  v_axis_count integer;
  v_index integer;
  v_on_ray boolean;
  v_coordinate integer;
  v_origin integer;
  v_direction integer;
begin
  select pieces into v_remaining from svela_private.puzzle_catalog where level_key = p_key and ranked;
  if not found or p_ids is null or pg_catalog.octet_length(p_ids::text) > 100000 or pg_catalog.jsonb_typeof(p_ids) <> 'array' then return false; end if;
  if pg_catalog.jsonb_array_length(p_ids) <> pg_catalog.jsonb_array_length(v_remaining) then return false; end if;
  for v_id in select value from pg_catalog.jsonb_array_elements(p_ids) loop
    if pg_catalog.jsonb_typeof(v_id) <> 'string' then return false; end if;
    select value into v_piece from pg_catalog.jsonb_array_elements(v_remaining) where value->'id' = v_id;
    if not found then return false; end if;
    v_axis := null; v_axis_count := 0;
    for v_index in 0..2 loop
      if (v_piece->'direction'->>v_index)::integer <> 0 then v_axis := v_index; v_axis_count := v_axis_count + 1; end if;
    end loop;
    if v_axis_count <> 1 then return false; end if;
    v_origin := (v_piece->'position'->>v_axis)::integer;
    v_direction := (v_piece->'direction'->>v_axis)::integer;
    -- The core is occupied permanently at [0,0,0].
    v_on_ray := true;
    for v_index in 0..2 loop
      if v_index <> v_axis and (v_piece->'position'->>v_index)::integer <> 0 then v_on_ray := false; end if;
    end loop;
    if v_on_ray and (0 - v_origin) * v_direction > 0 then return false; end if;
    for v_other in select value from pg_catalog.jsonb_array_elements(v_remaining) where value->'id' <> v_id loop
      v_on_ray := true;
      for v_index in 0..2 loop
        if v_index <> v_axis and v_other->'position'->v_index <> v_piece->'position'->v_index then v_on_ray := false; end if;
      end loop;
      v_coordinate := (v_other->'position'->>v_axis)::integer;
      if v_on_ray and (v_coordinate - v_origin) * v_direction > 0 then return false; end if;
    end loop;
    select coalesce(pg_catalog.jsonb_agg(value), '[]'::jsonb) into v_remaining from pg_catalog.jsonb_array_elements(v_remaining) where value->'id' <> v_id;
  end loop;
  return pg_catalog.jsonb_array_length(v_remaining) = 0;
end;
$$;

-- Keep the version-1 endpoint logic available only to this compatibility wrapper.
alter function public.save_game_progress(jsonb, integer) set schema svela_private;
alter function svela_private.save_game_progress(jsonb, integer) rename to save_game_progress_v1;
revoke all on function svela_private.save_game_progress_v1(jsonb, integer) from public, anon, authenticated, service_role;
create function public.save_game_progress(p_save jsonb, p_expected_revision integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_current public.game_progress%rowtype;
  v_key text;
  v_level jsonb;
  v_value jsonb;
begin
  v_uid := svela_private.require_account();
  if p_save->'version' = '1'::jsonb then return svela_private.save_game_progress_v1(p_save, p_expected_revision); end if;
  if p_expected_revision is null or p_expected_revision < 0 then raise exception 'Invalid expected revision' using errcode = '22023'; end if;
  if p_save is null or pg_catalog.jsonb_typeof(p_save) <> 'object' or pg_catalog.octet_length(p_save::text) > 2000000 then
    raise exception 'Invalid save or save too large' using errcode = '22023'; end if;
  if (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(p_save)) <> 6
    or not (p_save ?& array['version','activeLevel','completed','levels','bestTimes','tutorial'])
    or p_save->'version' <> '2'::jsonb
    or pg_catalog.jsonb_typeof(p_save->'activeLevel') <> 'string'
    or not exists (select 1 from svela_private.puzzle_catalog where level_key = p_save->>'activeLevel')
    or pg_catalog.jsonb_typeof(p_save->'completed') <> 'array'
    or pg_catalog.jsonb_typeof(p_save->'levels') <> 'object'
    or pg_catalog.jsonb_typeof(p_save->'bestTimes') <> 'object'
    or pg_catalog.jsonb_typeof(p_save->'tutorial') <> 'object' then
    raise exception 'Invalid save shape or version' using errcode = '22023'; end if;
  if pg_catalog.jsonb_array_length(p_save->'completed') > 5000
    or (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(p_save->'tutorial')) <> 2
    or not (p_save->'tutorial' ?& array['rotated','blockedSeen'])
    or pg_catalog.jsonb_typeof(p_save->'tutorial'->'rotated') <> 'boolean'
    or pg_catalog.jsonb_typeof(p_save->'tutorial'->'blockedSeen') <> 'boolean' then
    raise exception 'Invalid tutorial or completed list' using errcode = '22023'; end if;
  for v_value in select value from pg_catalog.jsonb_array_elements(p_save->'completed') loop
    if pg_catalog.jsonb_typeof(v_value) <> 'string' or not exists (select 1 from svela_private.puzzle_catalog where level_key = v_value #>> '{}') then
      raise exception 'Unknown completed level' using errcode = '22023'; end if;
  end loop;
  if (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(p_save->'completed')) <> (select pg_catalog.count(distinct value) from pg_catalog.jsonb_array_elements(p_save->'completed')) then
    raise exception 'Duplicate completed level' using errcode = '22023'; end if;
  for v_key, v_level in select key, value from pg_catalog.jsonb_each(p_save->'levels') loop
    if not exists (select 1 from svela_private.puzzle_catalog where level_key = v_key) or pg_catalog.jsonb_typeof(v_level) <> 'object' then
      raise exception 'Invalid level' using errcode = '22023'; end if;
    if (select pg_catalog.count(*) from pg_catalog.jsonb_object_keys(v_level)) not between 1 and 2 or not (v_level ? 'removedIds') or exists(select 1 from pg_catalog.jsonb_object_keys(v_level) as k where k not in ('removedIds','solutionIds')) or pg_catalog.jsonb_typeof(v_level->'removedIds') is distinct from 'array' then
      raise exception 'Invalid history' using errcode = '22023'; end if;
    if pg_catalog.jsonb_array_length(v_level->'removedIds') > 500 then raise exception 'History too long' using errcode = '22023'; end if;
    if v_level ? 'solutionIds' then
      if pg_catalog.jsonb_typeof(v_level->'solutionIds') <> 'array' then raise exception 'Invalid solution proof' using errcode = '22023'; end if;
      if pg_catalog.jsonb_array_length(v_level->'solutionIds') > 500 then raise exception 'Solution proof too long' using errcode = '22023'; end if;
      for v_value in select value from pg_catalog.jsonb_array_elements(v_level->'solutionIds') loop
        if pg_catalog.jsonb_typeof(v_value) <> 'string' or pg_catalog.length(v_value #>> '{}') not between 1 and 64 then raise exception 'Invalid solution identifier' using errcode = '22023'; end if;
      end loop;
    end if;
    for v_value in select value from pg_catalog.jsonb_array_elements(v_level->'removedIds') loop
      if pg_catalog.jsonb_typeof(v_value) <> 'string' or pg_catalog.length(v_value #>> '{}') not between 1 and 64 then raise exception 'Invalid piece' using errcode = '22023'; end if;
    end loop;
  end loop;
  for v_key, v_value in select key, value from pg_catalog.jsonb_each(p_save->'bestTimes') loop
    if not exists (select 1 from svela_private.puzzle_catalog where level_key = v_key) or pg_catalog.jsonb_typeof(v_value) <> 'number' or v_value::text !~ '^[0-9]{1,8}$' then raise exception 'Invalid personal best' using errcode = '22023'; end if;
    if v_value::text::bigint not between 1 and 86400000 then raise exception 'Personal best out of bounds' using errcode = '22023'; end if;
  end loop;
  select * into v_current from public.game_progress where user_id = v_uid;
  if found then
    if v_current.revision <> p_expected_revision then return pg_catalog.jsonb_build_object('ok',false,'save',v_current.save,'revision',v_current.revision,'updated_at',v_current.updated_at); end if;
    update public.game_progress set save = p_save, revision = revision + 1, updated_at = pg_catalog.clock_timestamp() where user_id = v_uid returning * into v_current;
  else
    if p_expected_revision <> 0 then return pg_catalog.jsonb_build_object('ok',false,'save',null,'revision',0,'updated_at',null); end if;
    insert into public.game_progress(user_id,save,revision,updated_at) values(v_uid,p_save,1,pg_catalog.clock_timestamp()) returning * into v_current;
  end if;
  return pg_catalog.jsonb_build_object('ok',true,'save',v_current.save,'revision',v_current.revision,'updated_at',v_current.updated_at);
end;
$$;

create function public.submit_discovery(p_level_key text, p_removed_ids jsonb) returns boolean
language plpgsql security definer set search_path = '' as $$
declare v_uid uuid;
begin
  v_uid := svela_private.require_account();
  if not svela_private.verify_solution(p_level_key,p_removed_ids) then raise exception 'Invalid complete solution' using errcode = '22023'; end if;
  insert into svela_private.verified_discoveries(user_id,level_key) values(v_uid,p_level_key) on conflict do nothing;
  return true;
end;
$$;
create function public.start_timed_run(p_level_key text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_uid uuid; v_id uuid; v_session text := auth.jwt()->>'session_id';
begin
  v_uid := svela_private.require_account();
  if v_session is null or not exists (select 1 from auth.sessions where id::text = v_session and user_id = v_uid) then raise exception 'Session expired' using errcode = '28000'; end if;
  if not exists (select 1 from svela_private.verified_discoveries where user_id = v_uid and level_key = p_level_key) then raise exception 'Discover level first' using errcode = '22023'; end if;
  -- A replacement start invalidates every older token, including other tabs.
  delete from svela_private.timed_runs where user_id = v_uid;
  insert into svela_private.timed_runs(user_id,session_id,level_key) values(v_uid,v_session,p_level_key) returning id into v_id;
  return pg_catalog.jsonb_build_object('id',v_id);
end;
$$;
create function public.finish_timed_run(p_run_id uuid, p_removed_ids jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_finished_at timestamptz := pg_catalog.clock_timestamp(); v_uid uuid; v_run svela_private.timed_runs%rowtype; v_elapsed integer; v_best integer; v_session text := auth.jwt()->>'session_id';
begin
  v_uid := svela_private.require_account();
  if v_session is null or not exists (select 1 from auth.sessions where id::text = v_session and user_id = v_uid) then raise exception 'Session expired' using errcode = '28000'; end if;
  select * into v_run from svela_private.timed_runs where id = p_run_id and user_id = v_uid and session_id = v_session for update;
  if not found then raise exception 'Unknown or consumed run' using errcode = '22023'; end if;
  if v_finished_at > v_run.started_at + interval '24 hours' then raise exception 'Run expired' using errcode = '22023'; end if;
  if not svela_private.verify_solution(v_run.level_key,p_removed_ids) then raise exception 'Invalid complete solution' using errcode = '22023'; end if;
  v_elapsed := greatest(1, pg_catalog.ceil(extract(epoch from (v_finished_at - v_run.started_at)) * 1000)::integer);
  if v_elapsed > 86400000 then raise exception 'Run expired' using errcode = '22023'; end if;
  delete from svela_private.timed_runs where id = p_run_id;
  insert into svela_private.level_bests(user_id,level_key,best_ms) values(v_uid,v_run.level_key,v_elapsed)
    on conflict (user_id,level_key) do update set best_ms = least(svela_private.level_bests.best_ms,excluded.best_ms) returning best_ms into v_best;
  return pg_catalog.jsonb_build_object('elapsed_ms',v_elapsed,'best_ms',v_best);
end;
$$;
create function public.get_leaderboard(p_kind text, p_level_key text default null, p_limit integer default 50, p_offset integer default 0)
returns table(rank bigint,name text,value bigint,is_you boolean)
language plpgsql security definer set search_path = '' as $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null or not exists (select 1 from auth.users where id = v_uid) then raise exception 'Authentication required' using errcode = '28000'; end if;
  if p_kind is null or p_kind not in ('discoveries','time') or p_limit is null or p_limit not between 1 and 50 or p_offset is null or p_offset not between 0 and 10000 then raise exception 'Invalid ranking parameters' using errcode = '22023'; end if;
  if p_kind = 'time' and (p_level_key is null or not exists (select 1 from svela_private.puzzle_catalog where level_key = p_level_key and ranked)) then raise exception 'Choose a campaign level' using errcode = '22023'; end if;
  return query
  with scores as (
    select d.user_id,pg_catalog.count(*)::bigint as score from svela_private.verified_discoveries d where p_kind = 'discoveries' group by d.user_id
    union all
    select b.user_id,b.best_ms::bigint from svela_private.level_bests b where p_kind = 'time' and b.level_key = p_level_key
  ), ranked_scores as (
    select s.user_id,s.score,pg_catalog.rank() over(order by case when p_kind = 'discoveries' then -s.score else s.score end) as position from scores s
  )
  select r.position,
    coalesce(nullif(pg_catalog.left(pg_catalog.btrim(u.raw_user_meta_data->>'display_name'),80),''), 'Esploratore ' || pg_catalog.left(pg_catalog.md5(u.id::text),8)),
    r.score,r.user_id = v_uid
  from ranked_scores r join auth.users u on u.id = r.user_id
  order by r.position,r.user_id limit p_limit offset p_offset;
end;
$$;
revoke all on all functions in schema svela_private from public, anon, authenticated, service_role;
revoke all on function public.save_game_progress(jsonb,integer),public.submit_discovery(text,jsonb),public.start_timed_run(text),public.finish_timed_run(uuid,jsonb),public.get_leaderboard(text,text,integer,integer) from public, anon, authenticated, service_role;
grant execute on function public.save_game_progress(jsonb,integer),public.submit_discovery(text,jsonb),public.start_timed_run(text),public.finish_timed_run(uuid,jsonb),public.get_leaderboard(text,text,integer,integer) to authenticated;
commit;
